const useAuthStore = create()(
  persist(
    (set, get) => ({
      user: null,
      isAuthenticated: false,
      isLoading: false,
      login: async ({ email, password: _password }) => {
        set({ isLoading: true });
        await new Promise((r2) => setTimeout(r2, 800));
        const found = MOCK_USERS.find((u) => u.email === email);
        if (found) {
          set({ user: found, isAuthenticated: true, isLoading: false });
          return true;
        }
        set({ isLoading: false });
        return false;
      },
      register: async (data) => {
        set({ isLoading: true });
        await new Promise((r2) => setTimeout(r2, 1e3));
        const newUser = {
          id: `u${Date.now()}`,
          name: data.name ?? "New User",
          email: data.email ?? "",
          role: data.role ?? "farmer",
          language: data.language ?? "en",
          location: data.location ?? "",
          phone: data.phone,
          farmSize: data.farmSize,
          cropTypes: data.cropTypes,
          animalTypes: data.animalTypes,
          createdAt: (/* @__PURE__ */ new Date()).toISOString()
        };
        set({ user: newUser, isAuthenticated: true, isLoading: false });
        return true;
      },
      logout: () => set({ user: null, isAuthenticated: false }),
      setLanguage: (lang) => {
        const user = get().user;
        if (user) set({ user: { ...user, language: lang } });
      },
      updateProfile: (data) => {
        const user = get().user;
        if (user) set({ user: { ...user, ...data } });
      }
    }),
    {
      name: "namwala-auth",
      partialize: (s2) => ({ user: s2.user, isAuthenticated: s2.isAuthenticated })
    }
  )
);
